package server

// Transaction Binding and Security
//
// A CMP transaction groups all messages in a single enrollment exchange (e.g., IR→IP→CertConf→PKIConf).
// The transactionID field in the PKIHeader identifies the transaction — it's a 128-bit random value
// generated by the client and echoed by the server in responses (RFC 9810 §5.1.1). When a
// client omits it, the server generates one and the client continues with that value.
//
// Since the transactionID is client-controlled, the server must prevent one client from
// hijacking another client's transaction by sending follow-up messages (CertConf, PollReq)
// with a guessed or observed transactionID.
//
// The solution is to use a composite key: hash(credentialID + transactionID). This ensures
// that two clients with different credentials have completely separate key spaces, even if
// they use the same transactionID. The credentialID is derived from what the server verified:
//   - MAC protection: hash of senderKID and the sender name, which together select the shared secret
//   - Signature protection: hash of the signer certificate
//
// This is secure because the credentialID is not client-controlled — it's derived from
// the cryptographic proof the client provided. An attacker would need the victim's
// shared secret or private key to produce a matching composite key.

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/binary"
	"errors"
	"sync"
	"sync/atomic"
	"time"

	"github.com/misiektoja/go-pki-cmp/pkicmp"
)

// transactionKey is a composite key derived from credentialID and transactionID.
// It ensures different clients cannot access each other's transactions.
type transactionKey [sha256.Size]byte

// credentialKey is a hash of the credentialID used for per-credential counting.
type credentialKey [sha256.Size]byte

// makeKey computes a composite key with length-prefixed components to prevent
// ambiguity from concatenation of variable-length inputs.
func makeKey(credentialID, transactionID []byte) transactionKey {
	h := sha256.New()
	var buf [4]byte
	binary.BigEndian.PutUint32(buf[:], uint32(len(credentialID))) // #nosec G115 -- CMP IDs are bounded by message size
	h.Write(buf[:])
	h.Write(credentialID)
	binary.BigEndian.PutUint32(buf[:], uint32(len(transactionID))) // #nosec G115 -- CMP IDs are bounded by message size
	h.Write(buf[:])
	h.Write(transactionID)
	var key transactionKey
	copy(key[:], h.Sum(nil))
	return key
}

// makeCredentialKey computes a hash of the credentialID for per-credential counting.
func makeCredentialKey(credentialID []byte) credentialKey {
	return credentialKey(sha256.Sum256(credentialID))
}

// newTransactionID returns a random 128-bit transactionID for a request that carried none.
func newTransactionID() []byte {
	id := make([]byte, 16)
	// crypto/rand.Read never returns an error. It crashes the program instead.
	_, _ = rand.Read(id)
	return id
}

// txnState represents the current phase of a transaction.
type txnState int

const (
	stateActive  txnState = iota // Transaction started, awaiting CA response
	statePending                 // CA returned "waiting", awaiting poll
	stateIssued                  // Certificate issued, awaiting certConf
	// Transaction done (implicit confirm granted), kept until cleanupExpired to
	// block transactionID reuse.
	stateCompleted
	// A popdecc challenge was sent and the request waits for the popdecr.
	// It comes last so the values saved in snapshots keep their meaning.
	stateChallenged
)

// transactionEntry holds all state for a single transaction.
// A transaction is in exactly one state at a time.
type transactionEntry struct {
	state         txnState
	lastActivity  time.Time
	credentialKey credentialKey

	// Set when state == statePending, stateIssued or stateChallenged
	reqType RequestType
	// popMethod is how the request proves possession of its key.
	popMethod POPMethod

	// Set when state == statePending
	pollRef      string
	senderNonce  []byte        // server's senderNonce from the waiting response (for recipNonce verification)
	lastPollTime time.Time     // last time a poll was received (zero for initial pending)
	checkAfter   time.Duration // minimum interval between polls, in whole seconds as advertised
	// implicitConfirm records that the delayed request asked for implicit
	// confirmation, which the pollReq that collects the certificate does not repeat.
	implicitConfirm bool
	// privateKey holds the DER EnvelopedData of a centrally generated private
	// key until the certificate is ready. Only the requester can decrypt it.
	// generatedKey holds the DER SubjectPublicKeyInfo of the pair.
	privateKey   []byte
	generatedKey []byte

	// Set when state == statePending or stateIssued
	//
	// certReqID is the certReqId of the delayed request while pending and of the
	// CertResponse that carried cert once issued. It is nil when the entry was
	// restored from a snapshot without it.
	certReqID *int64

	// Set when state == stateIssued
	//
	cert                *x509.Certificate
	issueRef            any    // opaque CA reference for CertificateConfirmer
	issuedSenderNonce   []byte // server's senderNonce from the issued response
	clientSenderNonce   []byte // client's senderNonce from the cert request
	protectionAlgorithm *pkicmp.AlgorithmIdentifier
	protectionParams    pkicmp.MACCredentialOption // decoded protection parameters for echo-back

	// Set when state == stateChallenged, together with senderNonce (the
	// popdecc's), certReqID and implicitConfirm.
	//
	// challengeRequest is the DER certificate request that the popdecr continues.
	challengeRequest []byte
	// challengeAnswer is the number the popdecc encrypted, as fixed-length big-endian bytes.
	challengeAnswer []byte
}

// transactionTracker manages transaction state for the CMP server.
// All methods require credentialID and transactionID, ensuring the composite key
// is always computed correctly. This prevents misuse by making it impossible to
// pass a raw key.
type transactionTracker struct {
	transactions sync.Map // transactionKey → *transactionEntry

	count                        atomic.Int64
	maxTransactions              int
	credentialCounts             sync.Map // credentialKey → *atomic.Int64
	maxTransactionsPerCredential int
}

func newTransactionTracker(maxTxn, maxPerCred int) *transactionTracker {
	return &transactionTracker{
		maxTransactions:              maxTxn,
		maxTransactionsPerCredential: maxPerCred,
	}
}

// startIfAbsent atomically creates a new transaction if one does not already exist.
// Returns (true, nil) if the transaction already existed, (false, nil) on success,
// or (false, err) if limits are exceeded.
func (t *transactionTracker) startIfAbsent(credentialID, transactionID []byte) (alreadyExists bool, err error) {
	key := makeKey(credentialID, transactionID)
	ck := makeCredentialKey(credentialID)

	// An existing transaction already holds its capacity, so a reused
	// transactionID is reported as in use rather than as a full server.
	// LoadOrStore below still catches a transaction stored concurrently.
	if _, ok := t.transactions.Load(key); ok {
		return true, nil
	}

	// Reserve capacity before storing to prevent transient overshoot.
	newCount := t.count.Add(1)
	if int(newCount) > t.maxTransactions {
		t.count.Add(-1)
		return false, errors.New("maximum transaction limit reached")
	}

	credCount := t.getOrCreateCredCount(ck)
	newCredCount := credCount.Add(1)
	if int(newCredCount) > t.maxTransactionsPerCredential {
		credCount.Add(-1)
		t.count.Add(-1)
		return false, errors.New("per-credential transaction limit reached")
	}

	entry := &transactionEntry{
		state:         stateActive,
		lastActivity:  time.Now(),
		credentialKey: ck,
	}

	// Atomically check existence and store.
	_, loaded := t.transactions.LoadOrStore(key, entry)
	if loaded {
		// Already existed — release reserved capacity.
		credCount.Add(-1)
		t.count.Add(-1)
		return true, nil
	}

	return false, nil
}

// getOrCreateCredCount returns the atomic counter for a credential key.
func (t *transactionTracker) getOrCreateCredCount(ck credentialKey) *atomic.Int64 {
	val, _ := t.credentialCounts.LoadOrStore(ck, &atomic.Int64{})
	return val.(*atomic.Int64)
}

// waitingState is what a waiting transaction keeps between polls.
type waitingState struct {
	reqType         RequestType
	certReqID       int64
	implicitConfirm bool
	popMethod       POPMethod
	// privateKey and generatedKey hold a centrally generated key pair, see transactionEntry.
	privateKey   []byte
	generatedKey []byte
	pollRef      string
	senderNonce  []byte
	checkAfter   time.Duration
	lastPollTime time.Time
}

// setPending moves an active, waiting or challenged transaction to the waiting state w describes.
func (t *transactionTracker) setPending(credentialID, transactionID []byte, w waitingState) bool {
	key := makeKey(credentialID, transactionID)
	ck := makeCredentialKey(credentialID)

	// Load current entry and verify expected state.
	old, ok := t.transactions.Load(key)
	if !ok {
		return false
	}
	oldEntry := old.(*transactionEntry)
	if oldEntry.state != stateActive && oldEntry.state != statePending && oldEntry.state != stateChallenged {
		return false
	}

	newEntry := &transactionEntry{
		state:           statePending,
		lastActivity:    time.Now(),
		credentialKey:   ck,
		reqType:         w.reqType,
		pollRef:         w.pollRef,
		senderNonce:     w.senderNonce,
		lastPollTime:    w.lastPollTime,
		checkAfter:      w.checkAfter,
		implicitConfirm: w.implicitConfirm,
		popMethod:       w.popMethod,
		privateKey:      w.privateKey,
		generatedKey:    w.generatedKey,
		certReqID:       &w.certReqID,
	}
	return t.transactions.CompareAndSwap(key, old, newEntry)
}

// waiting returns the state of a waiting entry, for a transition that keeps the request's details.
func (e *transactionEntry) waiting() waitingState {
	w := waitingState{
		reqType:         e.reqType,
		implicitConfirm: e.implicitConfirm,
		popMethod:       e.popMethod,
		privateKey:      e.privateKey,
		generatedKey:    e.generatedKey,
		pollRef:         e.pollRef,
		senderNonce:     e.senderNonce,
		checkAfter:      e.checkAfter,
		lastPollTime:    e.lastPollTime,
		certReqID:       -1,
	}
	if e.certReqID != nil {
		w.certReqID = *e.certReqID
	}
	return w
}

func (t *transactionTracker) getPending(credentialID, transactionID []byte) (*transactionEntry, bool) {
	v, ok := t.transactions.Load(makeKey(credentialID, transactionID))
	if !ok {
		return nil, false
	}
	entry := v.(*transactionEntry)
	if entry.state != statePending {
		return nil, false
	}
	return entry, true
}

// issuedState is what an issued transaction keeps until its certConf.
type issuedState struct {
	reqType   RequestType
	certReqID int64
	cert      *x509.Certificate
	issueRef  any
	popMethod POPMethod
	// senderNonce is the server's senderNonce in the response that carried cert.
	senderNonce []byte
	// clientSenderNonce is the senderNonce of the message that response answered.
	clientSenderNonce   []byte
	protectionParams    pkicmp.MACCredentialOption
	protectionAlgorithm *pkicmp.AlgorithmIdentifier
}

// setIssued retains the certificate and protection parameters needed for confirmation.
func (t *transactionTracker) setIssued(credentialID, transactionID []byte, is issuedState) bool {
	key := makeKey(credentialID, transactionID)
	ck := makeCredentialKey(credentialID)

	// Load current entry and verify expected state.
	old, ok := t.transactions.Load(key)
	if !ok {
		return false
	}
	oldEntry := old.(*transactionEntry)
	if oldEntry.state != stateActive && oldEntry.state != statePending && oldEntry.state != stateChallenged {
		return false
	}

	newEntry := &transactionEntry{
		state:               stateIssued,
		lastActivity:        time.Now(),
		credentialKey:       ck,
		reqType:             is.reqType,
		popMethod:           is.popMethod,
		certReqID:           &is.certReqID,
		cert:                is.cert,
		issueRef:            is.issueRef,
		issuedSenderNonce:   is.senderNonce,
		clientSenderNonce:   is.clientSenderNonce,
		protectionParams:    is.protectionParams,
		protectionAlgorithm: is.protectionAlgorithm,
	}
	return t.transactions.CompareAndSwap(key, old, newEntry)
}

// challengeState is what a challenged transaction keeps until the popdecr.
type challengeState struct {
	reqType         RequestType
	certReqID       int64
	implicitConfirm bool
	request         []byte
	answer          []byte
	senderNonce     []byte
}

// setChallenged moves an active transaction to the challenged state c describes.
func (t *transactionTracker) setChallenged(credentialID, transactionID []byte, c challengeState) bool {
	key := makeKey(credentialID, transactionID)
	old, ok := t.transactions.Load(key)
	if !ok || old.(*transactionEntry).state != stateActive {
		return false
	}
	newEntry := &transactionEntry{
		state:            stateChallenged,
		lastActivity:     time.Now(),
		credentialKey:    makeCredentialKey(credentialID),
		reqType:          c.reqType,
		popMethod:        POPChallengeResponse,
		certReqID:        &c.certReqID,
		implicitConfirm:  c.implicitConfirm,
		senderNonce:      c.senderNonce,
		challengeRequest: c.request,
		challengeAnswer:  c.answer,
	}
	return t.transactions.CompareAndSwap(key, old, newEntry)
}

// getChallenged returns the entry of a transaction that waits for a popdecr.
func (t *transactionTracker) getChallenged(credentialID, transactionID []byte) (*transactionEntry, bool) {
	v, ok := t.transactions.Load(makeKey(credentialID, transactionID))
	if !ok {
		return nil, false
	}
	entry := v.(*transactionEntry)
	if entry.state != stateChallenged {
		return nil, false
	}
	return entry, true
}

func (t *transactionTracker) getIssued(credentialID, transactionID []byte) (*transactionEntry, bool) {
	v, ok := t.transactions.Load(makeKey(credentialID, transactionID))
	if !ok {
		return nil, false
	}
	entry := v.(*transactionEntry)
	if entry.state != stateIssued {
		return nil, false
	}
	return entry, true
}

// setCompleted marks a transaction as done without deleting it, keeping the
// transactionID locked until cleanupExpired removes the entry. This prevents
// a client from reusing the same transactionID within the same confirmWaitTime
// window (RFC 9483 §3.5).
func (t *transactionTracker) setCompleted(credentialID, transactionID []byte) {
	key := makeKey(credentialID, transactionID)

	// Like every other transition, publish a fresh entry with CompareAndSwap.
	// cleanupExpired reads lastActivity concurrently, and a multi-word
	// time.Time updated in place can be read torn. Retry on a lost race so a
	// concurrent transition cannot leave the transaction uncompleted.
	for {
		old, ok := t.transactions.Load(key)
		if !ok {
			return
		}
		oldEntry := old.(*transactionEntry)

		newEntry := *oldEntry
		newEntry.state = stateCompleted
		newEntry.lastActivity = time.Now()

		if t.transactions.CompareAndSwap(key, old, &newEntry) {
			return
		}
	}
}

// remove deletes the transaction when its entry is still entry and reports
// whether it did, so that only one caller hears that the transaction ended.
func (t *transactionTracker) remove(credentialID, transactionID []byte, entry *transactionEntry) bool {
	if !t.transactions.CompareAndDelete(makeKey(credentialID, transactionID), entry) {
		return false
	}
	t.count.Add(-1)
	t.getOrCreateCredCount(entry.credentialKey).Add(-1)
	return true
}

func (t *transactionTracker) delete(credentialID, transactionID []byte) {
	key := makeKey(credentialID, transactionID)
	v, loaded := t.transactions.LoadAndDelete(key)
	if loaded {
		entry := v.(*transactionEntry)
		t.count.Add(-1)
		credCount := t.getOrCreateCredCount(entry.credentialKey)
		credCount.Add(-1)
	}
}

// expiredIssued holds details of an expired issued transaction for CA notification.
type expiredIssued struct {
	cert      *x509.Certificate
	issueRef  any
	popMethod POPMethod
}

// expiredEntries are the transactions one cleanup removed that their CA may want to hear about.
type expiredEntries struct {
	// issued are certificates that were never confirmed.
	issued []expiredIssued
	// waiting are the pollRefs of waiting requests whose client stopped polling.
	waiting []string
}

// cleanupExpired removes waiting entries idle for longer than waitingAge and
// every other entry idle for longer than maxAge. It returns the removed issued
// and waiting entries. A zero age keeps the entries it governs.
func (t *transactionTracker) cleanupExpired(maxAge, waitingAge time.Duration) expiredEntries {
	var expired expiredEntries
	now := time.Now()
	t.transactions.Range(func(key, value any) bool {
		entry := value.(*transactionEntry)
		age := maxAge
		if entry.state == statePending {
			age = waitingAge
		}
		if age <= 0 || !entry.lastActivity.Before(now.Add(-age)) {
			return true
		}
		// Only the entry read above is removed, so one that a concurrent request
		// replaced, for example by answering a poll, stays.
		if !t.transactions.CompareAndDelete(key, value) {
			return true
		}
		t.count.Add(-1)
		credCount := t.getOrCreateCredCount(entry.credentialKey)
		credCount.Add(-1)
		switch {
		case entry.state == stateIssued && entry.cert != nil:
			expired.issued = append(expired.issued, expiredIssued{
				cert:      entry.cert,
				issueRef:  entry.issueRef,
				popMethod: entry.popMethod,
			})
		case entry.state == statePending:
			expired.waiting = append(expired.waiting, entry.pollRef)
		}
		return true
	})
	return expired
}
